import{_ as e,o as a,c as r,ag as o}from"./chunks/framework.qXLDknWC.js";const u=JSON.parse('{"title":"Creating & Editing Characters","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/creating-characters.md","filePath":"getting-started/creating-characters.md"}'),n={name:"getting-started/creating-characters.md"};function i(s,t,l,d,c,g){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="creating-editing-characters" tabindex="-1">Creating &amp; Editing Characters <a class="header-anchor" href="#creating-editing-characters" aria-label="Permalink to &quot;Creating &amp; Editing Characters&quot;">​</a></h1><p>Character Vault provides two ways to create characters: generate them with AI or build them manually in the tabbed editor.</p><h2 id="creating-a-new-character" tabindex="-1">Creating a New Character <a class="header-anchor" href="#creating-a-new-character" aria-label="Permalink to &quot;Creating a New Character&quot;">​</a></h2><h3 id="option-1-ai-creation-studio" tabindex="-1">Option 1: AI Creation Studio <a class="header-anchor" href="#option-1-ai-creation-studio" aria-label="Permalink to &quot;Option 1: AI Creation Studio&quot;">​</a></h3><p>Generate a complete character card from scratch using AI:</p><ol><li>Click the <strong>✨ AI Creation Studio</strong> button in the vault header.</li><li>Choose your input mode: <ul><li><strong>Write Mode</strong> — Describe your character concept in free-form text</li><li><strong>Tags Mode</strong> — Select from curated tags across 6 categories</li></ul></li><li>Click <strong>Generate Character</strong> (or <strong>🎲 Feeling Lucky</strong> for random tags).</li><li>Review and edit the generated fields in the preview panel.</li><li>Click <strong>Save to Vault</strong> when ready.</li></ol><p>The AI generates a name, description, first message, and example dialogue automatically.</p><p><a href="/CharacterVault/docs/features/ai-creation-studio">Learn more about AI Creation Studio →</a></p><h3 id="option-2-manual-creation" tabindex="-1">Option 2: Manual Creation <a class="header-anchor" href="#option-2-manual-creation" aria-label="Permalink to &quot;Option 2: Manual Creation&quot;">​</a></h3><p>Build a character from scratch in the editor:</p><ol><li>Click the <strong>New</strong> button in the top right of the character library.</li><li>Enter a name for your character.</li><li>Click <strong>Create</strong>.</li></ol><p>Your new character opens in the workspace immediately, ready for editing.</p><h2 id="the-tabbed-editor" tabindex="-1">The Tabbed Editor <a class="header-anchor" href="#the-tabbed-editor" aria-label="Permalink to &quot;The Tabbed Editor&quot;">​</a></h2><p>The workspace organizes character fields into tabs. Click any tab to navigate to that section.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Section</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Image</strong></td><td style="text-align:left;">Upload a character portrait image</td></tr><tr><td style="text-align:left;"><strong>Name</strong></td><td style="text-align:left;">Your character&#39;s name</td></tr><tr><td style="text-align:left;"><strong>Description</strong></td><td style="text-align:left;">How the character looks, acts, and behaves</td></tr><tr><td style="text-align:left;"><strong>First Message</strong></td><td style="text-align:left;">The opening greeting users see when starting a conversation</td></tr><tr><td style="text-align:left;"><strong>Greetings</strong></td><td style="text-align:left;">Alternate opening messages (V2/V3 spec <code>alternate_greetings</code>)</td></tr><tr><td style="text-align:left;"><strong>Examples</strong></td><td style="text-align:left;">Sample dialogue showing how the character talks (<code>mes_example</code>)</td></tr><tr><td style="text-align:left;"><strong>Scenario</strong></td><td style="text-align:left;">The setting or situation for roleplay</td></tr><tr><td style="text-align:left;"><strong>Appearance</strong></td><td style="text-align:left;">Physical description details (V3 <code>physical_description</code>)</td></tr><tr><td style="text-align:left;"><strong>Personality</strong></td><td style="text-align:left;">Personality traits and quirks</td></tr><tr><td style="text-align:left;"><strong>System</strong></td><td style="text-align:left;">Instructions for the AI about how to play the character (<code>system_prompt</code>)</td></tr><tr><td style="text-align:left;"><strong>Lorebook</strong></td><td style="text-align:left;">Extra information that triggers on keywords (<code>character_book</code>)</td></tr><tr><td style="text-align:left;"><strong>Creator</strong></td><td style="text-align:left;">Your name (optional)</td></tr><tr><td style="text-align:left;"><strong>Creator Notes</strong></td><td style="text-align:left;">Notes for other users — supports HTML/CSS with live preview</td></tr><tr><td style="text-align:left;"><strong>Tags</strong></td><td style="text-align:left;">Keywords to categorize your character</td></tr></tbody></table><h2 id="name-creator-and-tags" tabindex="-1">Name, Creator, and Tags <a class="header-anchor" href="#name-creator-and-tags" aria-label="Permalink to &quot;Name, Creator, and Tags&quot;">​</a></h2><p>The <strong>Name</strong> and <strong>Creator</strong> tabs use simple text boxes. Type directly into the field and your change is saved automatically.</p><p>The <strong>Tags</strong> tab is built for quick editing:</p><ul><li>Type a tag and press <strong>Enter</strong> to add it.</li><li>Type several tags separated by commas to add them at once.</li><li>Paste a comma-separated list to add many tags quickly.</li><li>Click the <strong>x</strong> on a tag to remove it.</li><li>Duplicate tags are skipped automatically.</li></ul><h2 id="auto-save" tabindex="-1">Auto-Save <a class="header-anchor" href="#auto-save" aria-label="Permalink to &quot;Auto-Save&quot;">​</a></h2><p>All changes are saved automatically as you type. There&#39;s no need to click a save button.</p><h2 id="image-support" tabindex="-1">Image Support <a class="header-anchor" href="#image-support" aria-label="Permalink to &quot;Image Support&quot;">​</a></h2><p>On the <strong>Image</strong> tab you can:</p><ul><li><strong>Upload</strong> a new portrait from your device.</li><li><strong>Replace</strong> an existing portrait by uploading a new image.</li></ul><p>Character Vault generates a 128×192 JPEG thumbnail for the library grid view automatically.</p><h2 id="lorebook-world-info" tabindex="-1">Lorebook / World Info <a class="header-anchor" href="#lorebook-world-info" aria-label="Permalink to &quot;Lorebook / World Info&quot;">​</a></h2><p>The <strong>Lorebook</strong> tab edits the world info that lives <strong>on the character</strong> and exports with the card. Each entry can include:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Entry title</strong></td><td style="text-align:left;">Display memo (not injected as content)</td></tr><tr><td style="text-align:left;"><strong>Primary keys</strong></td><td style="text-align:left;">Keywords or <code>/regex/</code> that can activate the entry</td></tr><tr><td style="text-align:left;"><strong>Secondary keys / selective</strong></td><td style="text-align:left;">Optional filters and ST selective logic</td></tr><tr><td style="text-align:left;"><strong>Content</strong></td><td style="text-align:left;">Text injected when the entry activates</td></tr><tr><td style="text-align:left;"><strong>Insertion order</strong></td><td style="text-align:left;">Order among activated entries</td></tr><tr><td style="text-align:left;"><strong>Position</strong></td><td style="text-align:left;">Before/after char or examples, or at chat depth</td></tr><tr><td style="text-align:left;"><strong>Enabled / Constant</strong></td><td style="text-align:left;">Off entirely, or always-on without keys</td></tr><tr><td style="text-align:left;"><strong>Case sensitive / whole words</strong></td><td style="text-align:left;">Key matching options</td></tr><tr><td style="text-align:left;"><strong>Probability</strong></td><td style="text-align:left;">Optional chance after a match</td></tr><tr><td style="text-align:left;"><strong>Recursion flags</strong></td><td style="text-align:left;">Non-recursable, prevent further, delay until recursion</td></tr></tbody></table><p>Also available: AI context eye toggles, AI key generation, book-level scan depth / token budget / recursive scanning, and a <strong>recursion map</strong> for who unlocks whom. Extra World Info fields live under <strong>Options</strong> so the content editor stays in view.</p><p>For the full two-panel editor, see <a href="/CharacterVault/docs/features/lorebook-editor">Lorebook Editor</a>.</p><h3 id="library-books-and-linking" tabindex="-1">Library books and linking <a class="header-anchor" href="#library-books-and-linking" aria-label="Permalink to &quot;Library books and linking&quot;">​</a></h3><p>The home screen <strong>Lorebooks</strong> tab holds books you can edit without opening a character. Link one book to a character (several characters can share it). After that, <strong>Open in vault</strong> and edits in the library workspace keep the two sides together. Exporting the card includes the lorebook on the character. See <a href="/CharacterVault/docs/features/lorebook-vault#attach-to-a-character-vault-local">Lorebook Vault → Linking</a>.</p><h2 id="creator-notes" tabindex="-1">Creator Notes <a class="header-anchor" href="#creator-notes" aria-label="Permalink to &quot;Creator Notes&quot;">​</a></h2><p>The Creator Notes tab supports <strong>HTML and CSS</strong> with a sandboxed live preview — useful for sharing styled notes, credits, or usage instructions with other users who import your card. See <a href="/CharacterVault/docs/features/creator-notes">Creator Notes Preview</a> for details.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/features/lorebook-editor">Lorebook editor deep dive</a></li><li><a href="/CharacterVault/docs/features/lorebook-vault">Lorebook Vault</a></li><li><a href="/CharacterVault/docs/features/creator-notes">Creator Notes preview</a></li><li><a href="/CharacterVault/docs/features/ai-assistant">Use the AI assistant to brainstorm content</a></li><li><a href="/CharacterVault/docs/features/import-export">Import existing character cards</a></li><li><a href="/CharacterVault/docs/features/snapshots-history">Learn about snapshot history and rollback</a></li></ul>',36)])])}const p=e(n,[["render",i]]);export{u as __pageData,p as default};
